void write(json::Writer& w, const PairingRequest& value)
{
    w.begin_object();
    w.key("schema");
    w.number(std::uint64_t{1});
    w.key("device");
    w.string(value.device);
    w.key("scopes");
    w.begin_array();
    for (const auto& item : value.scopes)
    {
        w.string(item);
    }
    w.end_array();
    if (value.key)
    {
        w.key("key");
        write(w, *value.key);
    }
    if (!value.invitation.empty())
    {
        w.key("invitation");
        w.string(value.invitation);
    }
    w.end_object();
}

void write(json::Writer& w, const UploadRequest& value)
{
    w.begin_object();
    w.key("schema");
    w.number(std::uint64_t{1});
    w.key("size");
    w.number(value.size);
    w.key("sha256");
    {
        const auto hex = to_hex(value.sha256);
        w.string(std::string_view(hex.data(), hex.size()));
    }
    if (!value.kind.empty())
    {
        w.key("kind");
        w.string(value.kind);
    }
    if (!value.slot.empty())
    {
        w.key("slot");
        w.string(value.slot);
    }
    if (value.game_version_code)
    {
        w.key("game_version_code");
        w.number(*value.game_version_code);
    }
    if (!value.profile.empty())
    {
        w.key("profile");
        w.string(value.profile);
    }
    if (!value.note.empty())
    {
        w.key("note");
        w.string(value.note);
    }
    w.end_object();
}

